import { MakeLogicType, afterMount, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'
import { hogql } from 'lib/utils/hogql'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface surveysShownRecentlyLogicValues {
    surveysShownRecently: boolean | null
    surveysShownRecentlyLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface surveysShownRecentlyLogicActions {
    loadSurveysShownRecently: () => any
    loadSurveysShownRecentlyFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSurveysShownRecentlySuccess: (
        surveysShownRecently: boolean | null,
        payload?: any
    ) => {
        surveysShownRecently: boolean | null
        payload?: any
    }
}

export type surveysShownRecentlyLogicType = MakeLogicType<
    surveysShownRecentlyLogicValues,
    surveysShownRecentlyLogicActions
>

export const surveysShownRecentlyLogic = kea<surveysShownRecentlyLogicType>([
    path(['products', 'surveys', 'frontend', 'components', 'WorkflowSurveyPicker', 'surveysShownRecentlyLogic']),
    loaders({
        // null until loaded, and when the check fails, so a failed check never shows a warning.
        surveysShownRecently: [
            null as boolean | null,
            {
                loadSurveysShownRecently: async (): Promise<boolean | null> => {
                    try {
                        const response = await api.queryHogQL(
                            hogql`SELECT 1 FROM events WHERE event = 'survey shown' AND timestamp > now() - INTERVAL 30 DAY LIMIT 1`,
                            { productKey: 'surveys', name: 'workflow_survey_step_recent_survey_shown' }
                        )
                        return (response.results?.length ?? 0) > 0
                    } catch {
                        return null
                    }
                },
            },
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadSurveysShownRecently()
    }),
])
